sealed class Figura
class Circulo(val r: Double): Figura()
class Cuadrado(val lado: Double): Figura()

fun area(f: Figura): Double = when (f) {
    is Circulo -> Math.PI * f.r * f.r
    is Cuadrado -> f.lado * f.lado
}
println(area(Cuadrado(4.0)))

